import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with dueDate on or after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate = 2026-10-21

  const result = overdueInvoices([issued.value], '2026-10-21');
  assert.equal(result.length, 0);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate = 2026-10-21

  const result = overdueInvoices([issued.value], '2026-10-22');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);

  const result = overdueInvoices([inv.value], '2026-10-30');
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  invoice = recordPayment(invoice, { amount: 114950, date: '2026-10-08' }).value;

  const result = overdueInvoices([invoice], '2026-10-30');
  assert.equal(result.length, 0);
});

test('overdueInvoices includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-30');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  invoice = recordPayment(invoice, { amount: 50000, date: '2026-10-08' }).value;

  const result = overdueInvoices([invoice], '2026-10-30');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate = 2026-10-21

  const result = overdueInvoices([issued.value], '2026-10-31');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices includes invoice number', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-30');
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices includes customerId', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-30');
  assert.equal(result[0].customerId, 'C-002');
});

test('overdueInvoices includes dueDate', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-30');
  assert.equal(result[0].dueDate, '2026-10-21');
});

test('overdueInvoices includes due amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = overdueInvoices([issued.value], '2026-10-30');
  assert.equal(result[0].due, 114950);
});

test('overdueInvoices reflects partial payments in due amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  assert.equal(inv.ok, true);
  let invoice = issueInvoice(inv.value, []).value;
  invoice = recordPayment(invoice, { amount: 50000, date: '2026-10-08' }).value;

  const result = overdueInvoices([invoice], '2026-10-30');
  assert.equal(result[0].due, 64950);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv3.ok, true);
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = overdueInvoices([issued1.value, issued2.value, issued3.value], '2026-10-30');
  assert.equal(result.length, 3);
  // inv1: dueDate 2026-10-15, 15 days overdue
  // inv2: dueDate 2026-10-21, 9 days overdue
  // inv3: dueDate 2026-10-19, 11 days overdue
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[1].number, 'INV-2026-0003');
  assert.equal(result[2].number, 'INV-2026-0002');
  assert(result[0].daysOverdue >= result[1].daysOverdue);
  assert(result[1].daysOverdue >= result[2].daysOverdue);
});

test('overdueInvoices with multiple customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-30');
  assert.equal(result.length, 2);
  const customers = result.map((r) => r.customerId);
  assert(customers.includes('C-001'));
  assert(customers.includes('C-002'));
});

test('overdueInvoices handles invoices with different terms', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-30');
  // inv1: dueDate = 2026-10-21, 9 days overdue
  // inv2: dueDate = 2026-11-06, not overdue yet
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

test('overdueInvoices with EOM terms', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // dueDate = 2026-10-31

  const result = overdueInvoices([issued.value], '2026-11-01');
  assert.equal(result.length, 1);
